package com.bank.batch;

import java.util.ArrayList;
import java.util.List;

class BatchSplitter {

    // One pass: route each id into evens or odds using modulo.
    SplitResult split(int[] batchIds) {
        List<Integer> evens = new ArrayList<>();
        List<Integer> odds = new ArrayList<>();
        for (int id : batchIds) {
            if (id % 2 == 0) {          // no remainder → even
                evens.add(id);
            } else {                    // remainder != 0 → odd (handles negatives)
                odds.add(id);
            }
        }
        return new SplitResult(evens, odds);
    }
}
